1. using Microsoft.ML;
2. using Microsoft.ML.Data;
3. using Microsoft.Extensions.ML;
4. 
5. var builder = WebApplication.CreateBuilder(args);
6. 
7. // Train and save the model at startup
8. var mlContext = new MLContext(seed: 42);
9. var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "customers.csv");
10. var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "ChurnModel.zip");
11. 
12. var dataView = mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ',');
13. 
14. var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region))
15.     .Append(mlContext.Transforms.Concatenate("Features", nameof(CustomerData.Age),
16.         nameof(CustomerData.Income), nameof(CustomerData.PurchaseHistory), "RegionEncoded"))
17.     .Append(mlContext.Transforms.NormalizeMinMax("Features"))
18.     .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
19.         labelColumnName: nameof(CustomerData.Churned), featureColumnName: "Features"));
20. 
21. var rowCount = (int)dataView.GetRowCount()!;
22. 
23. ITransformer model;
24. if (rowCount >= 20)
25. {
26.     var split = mlContext.Data.TrainTestSplit(dataView, testFraction: 0.2);
27.     model = pipeline.Fit(split.TrainSet);
28.     var predictions = model.Transform(split.TestSet);
29.     var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: nameof(CustomerData.Churned));
30.     Console.WriteLine($"Model metrics — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");
31. }
32. else
33. {
34.     Console.WriteLine($"Small dataset ({rowCount} rows) — training on all data. Add more rows for evaluation metrics.");
35.     model = pipeline.Fit(dataView);
36. }
37. 
38. mlContext.Model.Save(model, dataView.Schema, modelPath);
39. 
40. // Register pooled prediction engine (thread-safe)
41. builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
42.     .FromFile(modelPath);
43. 
44. var app = builder.Build();
45. 
46. app.MapGet("/", () => "Churn Predictor API — POST /predict with Age, Income, Region, PurchaseHistory");
47. 
48. app.MapPost("/predict", (PredictionEnginePool<CustomerData, ChurnPrediction> pool, CustomerInput input) =>
49. {
50.     var customerData = new CustomerData
51.     {
52.         Age = input.Age,
53.         Income = input.Income,
54.         Region = input.Region,
55.         PurchaseHistory = input.PurchaseHistory
56.     };
57.     var prediction = pool.Predict(customerData);
58.     return Results.Ok(new
59.     {
60.         WillChurn = prediction.PredictedLabel,
61.         Confidence = prediction.Probability
62.     });
63. });
64. 
65. app.Run();
66. 
